TREES = {
    "oak": ("Dall'Europa al Caucaso", "Un albero ampio e longevo con foglie lobate e ghiande. Una sola quercia ospita centinaia di specie di insetti, e il suo legno ha costruito le navi e le cattedrali d'Europa per mille anni."),
    "birch": ("Europa e Asia settentrionale", "Una pioniera snella dalla corteccia bianca che si sfoglia in strisce sottili come carta. La corteccia è impermeabile e brucia anche umida; ci si facevano canoe, scatole e le prime lettere scritte di Novgorod."),
    "spruce": ("Europa settentrionale e centrale", "Una conifera alta e conica con aghi corti e quadrati e pigne pendenti. Il suo legno leggero e regolare fa le tavole armoniche di violini e pianoforti; è il classico albero di Natale."),
    "jungle": ("", "Un albero solo di questo mondo: un tronco altissimo di foresta pluviale coperto di liane e baccelli di cacao. Le vere foreste pluviali contano centinaia di specie di alberi in un solo ettaro."),
    "acacia": ("Africa e penisola arabica", "L'acacia a ombrello: una chioma piatta di foglioline su un tronco biforcuto, armata di lunghe spine. Le giraffe superano le spine con lingue lunghe mezzo metro."),
    "dark_oak": ("", "Un albero solo di questo mondo: una quercia massiccia a quattro tronchi che ombreggia così tanto il sottobosco che sotto crescono funghi giganti."),
    "mangrove": ("Coste tropicali dell'Atlantico e del Pacifico orientale", "La mangrovia rossa poggia su radici a trampolo arcuate nell'acqua salata. I suoi semi germogliano ancora sull'albero e cadono come lance che galleggiano per mesi prima di radicare."),
    "cherry": ("Giappone, Corea e Cina", "Il ciliegio da fiore giapponese: coltivato per le sue nuvole di fiori rosa, non per i frutti. La sua breve fioritura ogni primavera è celebrata in Giappone come hanami."),
    "azalea": ("Montagne di Asia, Europa e America settentrionale", "Le azalee sono rododendri arbustivi con fiori a imbuto. Il miele di alcune specie è velenoso; in questo mondo segnalano le grotte lussureggianti sottostanti."),
    "mahogany": ("Dal Messico all'Amazzonia meridionale", "Il mogano a foglia larga: un gigante diritto dal legno rossastro e stabile. Secoli di taglio per mobili pregiati lo hanno reso raro, e oggi il suo commercio è regolato da un trattato."),
    "brazil_nut": ("Foresta amazzonica", "Uno degli alberi più alti dell'Amazzonia. Le sue noci crescono dentro una palla dura grande come una noce di cocco che solo l'aguti sa rosicchiare; l'aguti sotterra le noci in più e pianta nuovi alberi."),
    "brazilwood": ("Foresta atlantica del Brasile", "Un albero spinoso dal durame rosso arancio che ha dato il nome al Brasile. La sua tintura rossa partiva per l'Europa dal 1501; oggi il suo legno fa i migliori archetti per violino."),
    "sapodilla": ("Messico meridionale e America centrale", "Un sempreverde dai frutti marroni e dolci che sanno di pera e malto. Il suo lattice, il chicle, fu la prima gomma da masticare."),
    "andiroba": ("Bacino amazzonico e Caraibi", "Un parente del mogano della foresta pluviale con grandi frutti legnosi. L'olio amaro spremuto dai semi si usa contro le punture di insetti e come olio per lampade."),
    "acai": ("Estuario del Rio delle Amazzoni", "Una palma sottile che cresce a cespi sulle rive allagate. Le sue bacche viola sono un alimento base alla foce del Rio delle Amazzoni, e il suo germoglio si mangia come cuore di palma."),
    "babassu": ("Amazzonia orientale e Nordest del Brasile", "Una palma alta con enormi fronde erette. Le sue noci dure contengono un olio molto simile a quello di cocco; nel Maranhão le donne le spaccano a mano con un'ascia e un bastone."),
    "copaiba": ("Brasile, Paraguay e Bolivia", "Un albero il cui tronco contiene una resina oleosa che sgorga da un foro. Il balsamo di copaiba si vendeva nelle farmacie europee dal Seicento."),
    "cinchona": ("Ande di Ecuador e Perù", "Un piccolo albero andino la cui corteccia amara contiene il chinino, la prima cura della malaria. Compare nello stemma del Perù."),
    "oil_palm": ("Africa occidentale e centrale", "Una palma a foglie pennate i cui caschi di frutti arancioni danno l'olio di palma, l'olio vegetale più prodotto al mondo. Un casco può pesare 40 chili."),
    "teak": ("India, Myanmar, Laos e Thailandia", "Un albero alto e deciduo con foglie grandi come un piatto. Il suo legno dorato e oleoso resiste all'acqua e alle termiti, perciò era il legno dei ponti delle navi."),
    "cinnamon": ("Sri Lanka e India meridionale", "Un alloro sempreverde la cui corteccia interna, staccata ed essiccata, si arrotola in stecche di cannella. Il profumo viene dall'aldeide cinnamica."),
    "camphor_laurel": ("Cina, Giappone e Corea", "Un ampio sempreverde le cui foglie stropicciate odorano di canfora. La canfora distillata dal suo legno servì per la celluloide, la prima pellicola di plastica."),
    "sal": ("Pendici dell'Himalaya in India e Nepal", "Un albero alto, quasi sempreverde, che forma intere foreste. Il suo legno duro regge le case indiane e la sua resina si brucia come incenso; si dice che il Buddha sia nato sotto uno di essi."),
    "nutmeg": ("Isole Banda, Indonesia", "Un sempreverde il cui seme è la noce moscata e il cui arillo rosso è il macis. Si combatterono guerre per le minuscole isole Banda, l'unico luogo dove cresceva."),
    "baobab": ("Africa tropicale", "Un enorme tronco a bottiglia che accumula acqua per la stagione secca. I baobab possono vivere oltre 2.000 anni; la polpa secca del frutto è ricca di vitamina C."),
    "gum_arabic_tree": ("Sahel e Sudan", "Un piccolo albero spinoso del Sahel. La sua linfa indurisce in gomma arabica, usata in bibite, francobolli, acquerelli e inchiostri da stampa."),
    "marula": ("Africa australe e orientale", "Un albero della savana con frutti gialli grandi come prugne amati dagli elefanti. Dal frutto si fanno birra e liquore, e le noci danno un olio stabile."),
    "shea": ("Savana dell'Africa occidentale e centrale", "Un albero a crescita lenta che fruttifica per la prima volta dopo 15 anni. Le sue noci danno il burro di karité, un grasso per cibo, sapone e cioccolato."),
    "eucalyptus": ("Tasmania e Australia sudorientale", "L'eucalipto blu della Tasmania: un gigante a crescita rapida con corteccia che si sfoglia e foglie giovani azzurrine. Il suo olio, l'eucaliptolo, libera il naso; le sue piantagioni riforniscono le cartiere di tutto il mondo."),
    "pequi": ("Cerrado del Brasile", "Un albero contorto del cerrado con un frutto giallo dal profumo intenso. Sotto la polpa il seme nasconde spine sottili, perciò il frutto si rosicchia, non si morde mai."),
    "barbatimao": ("Cerrado del Brasile", "Un piccolo albero del cerrado dalla corteccia spessa e sugherosa. La corteccia è così ricca di tannino che si usava per conciare il cuoio e curare le ferite."),
    "yellow_ipe": ("Sudamerica tropicale", "Nella stagione secca perde ogni foglia e fiorisce di un giallo vivo. Il suo legno, l'ipè, è uno dei più duri e densi del mondo."),
    "jatoba": ("America centrale e meridionale", "Un grande albero con foglioline a coppie e baccelli pieni di una polpa dolce e farinosa. La sua resina, il copale, si è trasformata in ambra in milioni di anni."),
    "sandalwood": ("India, Indonesia e Australia settentrionale", "Un emiparassita le cui radici attingono acqua dalle radici di altre piante. Il durame profumato e l'olio valgono tanto che gli alberi selvatici sono stati tagliati quasi tutti."),
    "dragon_tree": ("Isola di Socotra, Yemen", "Un ombrello di foglie rigide su rami spessi, che cresce solo a Socotra. La sua resina rossa, il sangue di drago, era un pigmento e una vernice nel mondo antico."),
    "frankincense": ("Oman, Yemen e Somalia", "Un piccolo albero che cresce sulla roccia nuda. I tagli nella sua corteccia cartacea trasudano una resina lattiginosa che secca in incenso, commerciato in Arabia da 5.000 anni."),
    "myrrh": ("Corno d'Africa e Arabia meridionale", "Un alberello spinoso dei suoli secchi e sassosi. La sua resina rossastra, la mirra, serviva per profumi, medicine e imbalsamazione nell'antico Egitto."),
    "date_palm": ("Medio Oriente e Nordafrica", "La palma coltivata del deserto, piantata nelle oasi da almeno 7.000 anni. Gli alberi femmina portano grappoli fino a mille datteri ciascuno."),
    "mesquite": ("Messico, America centrale e Caraibi", "Un albero spinoso con radici che raggiungono l'acqua a 50 metri di profondità. I suoi baccelli dolci nutrono il bestiame e i popoli del deserto li macinavano in farina."),
    "joshua_tree": ("Deserto del Mojave", "Una yucca gigante con braccia ramificate e appuntite, non un vero albero. Una sola falena impollina i suoi fiori, e le sue larve mangiano solo i suoi semi."),
    "saxaul": ("Deserti dell'Asia centrale", "Un albero del deserto senza foglie, con rametti verdi al loro posto. Il suo legno è così denso che affonda nell'acqua e brucia come carbone."),
    "argan": ("Marocco sudoccidentale", "Un albero spinoso resistente alla siccità su cui le capre si arrampicano per mangiare i frutti. I suoi semi danno l'olio di argan, per cucina e cosmetici."),
    "palo_verde": ("Deserto di Sonora", "Il nome significa bastone verde: la corteccia è verde e fa quasi tutta la fotosintesi quando le foglioline cadono con la siccità. In primavera si copre di fiori gialli."),
    "pinyon_pine": ("Altopiano del Colorado e Sudovest degli Stati Uniti", "Un pino piccolo e lento delle colline secche. I suoi grandi pinoli furono un cibo principale dei popoli del Grande Bacino e si raccolgono ancora ogni autunno."),
    "utah_juniper": ("Grande Bacino e altopiano del Colorado", "Un ginepro nodoso dei pendii secchi che può vivere 650 anni. Le sue bacche blu sono in realtà coni carnosi, mangiati dagli uccelli."),
    "desert_ironwood": ("Deserto di Sonora", "Uno dei legni più pesanti del mondo: affonda nell'acqua. Molte piante del deserto iniziano la vita alla sua ombra, perciò lo chiamano albero nutrice."),
    "tamarisk": ("Dal Nordafrica all'India", "Un cedro salato con minuscole foglie a squama che trasudano sale. Cresce dove l'acqua del suolo è troppo salata per altri alberi."),
    "ponderosa_pine": ("Nordamerica occidentale", "Un pino alto dalla corteccia arancione a placche che sa di vaniglia nei giorni caldi. La corteccia spessa gli permette di sopravvivere ai fuochi radenti che attraversano le sue foreste."),
    "gambel_oak": ("Sudovest degli Stati Uniti e Montagne Rocciose", "Una quercia arbustiva che si allarga con le radici in boscaglie. Le sue ghiande nutrivano cervi, tacchini e i popoli della regione."),
    "mountain_mahogany": ("Montagne del Nordamerica occidentale", "Non un mogano ma un parente della rosa. I suoi semi hanno una coda piumosa che si attorciglia con l'umidità e trivella il seme nel terreno."),
    "elephant_tree": ("Deserto di Sonora e Bassa California", "Un albero tozzo con un tronco gonfio che accumula acqua e corteccia che si sfoglia come carta. I suoi rametti odorano di trementina e danno una resina di copale."),
    "coconut_palm": ("Coste tropicali dell'oceano Indiano e del Pacifico", "La palma delle spiagge tropicali. La sua noce galleggia e resta viva per mesi in mare, ed è così che si è diffusa attraverso gli oceani."),
    "tropical_almond": ("Asia tropicale, Australia e Pacifico", "Un albero da spiaggia con rami a piani e grandi foglie che diventano rosse prima di cadere. I semi sanno di mandorla, e le foglie cadute tingono l'acqua di bruno col tannino."),
    "casuarina": ("Sudest asiatico, Australia e Pacifico", "Sembra un pino ma è un albero da fiore con rametti verdi articolati. Le sue radici fissano l'azoto, perciò cresce sulla sabbia nuda."),
    "screw_pine": ("Coste del Pacifico e dell'oceano Indiano", "Le foglie girano a spirale intorno al tronco come una vite, e radici a trampolo lo tengono dritto nella sabbia. Con le sue foglie si intrecciano stuoie e tetti."),
    "sea_grape": ("Coste dell'America tropicale", "Un albero da spiaggia tollerante al sale con foglie rotonde e coriacee. I suoi frutti viola pendono in grappoli come l'uva e danno una gelatina aspra."),
    "black_mangrove": ("Coste tropicali atlantiche e pacifiche delle Americhe", "Una mangrovia le cui radici spingono attraverso il fango germogli respiratori simili a matite. Espelle il sale dalle foglie, che luccicano di cristalli."),
    "white_mangrove": ("Coste tropicali atlantiche delle Americhe e dell'Africa occidentale", "Cresce sul lato della mangrovia verso terra. Due piccole ghiandole alla base di ogni foglia emettono zucchero e sale."),
    "buttonwood": ("Coste tropicali delle Americhe e dell'Africa occidentale", "Una mangrovia della riva alta con capolini di semi simili a bottoni. Il suo legno denso si bruciava per farne carbone nei Caraibi."),
    "nipa_palm": ("Mangrovie dell'Asia e del Pacifico occidentale", "Una palma senza fusto visibile il cui tronco corre sotto il fango, con solo le fronde in superficie. La sua linfa dolce si raccoglie per zucchero, aceto e alcol."),
    "buriti": ("Zone umide dell'Amazzonia e del Cerrado", "Una palma alta a ventaglio di paludi e rive. Il suo frutto rosso e squamoso è ricchissimo di vitamina A; con la fibra delle foglie si intrecciano amache."),
    "eastern_cottonwood": ("Nordamerica orientale e centrale", "Un pioppo a crescita rapida dei fondovalle fluviali, con foglie triangolari. A inizio estate i suoi semi volano via su ciuffi di cotone bianco."),
    "american_elm": ("Nordamerica orientale", "Un albero a forma di vaso che un tempo fiancheggiava le strade delle città americane. La grafiosi, un fungo diffuso dai coleotteri, ne uccise la maggior parte dopo il 1930."),
    "ash": ("Dall'Europa al Caucaso", "Un albero alto con foglie pennate e gemme nere d'inverno. Il suo legno tenace ed elastico fece manici di attrezzi, remi e archi; il deperimento del frassino, un fungo, oggi lo minaccia."),
    "walnut": ("Dall'Asia centrale ai Balcani", "Il noce comune: un albero ampio con foglie aromatiche e noci commestibili. Le sue radici rilasciano juglone, che impedisce a molte altre piante di crescere vicino."),
    "white_mulberry": ("Cina settentrionale", "Un piccolo albero le cui foglie sono l'unico cibo del baco da seta. Gli stami dei suoi fiori scattano più veloci di qualsiasi altro movimento vegetale noto, lanciando il polline."),
    "linden": ("Europa e Siberia occidentale", "Il tiglio selvatico: foglie a cuore e fiori profumati amati dalle api. Il suo legno tenero e bianco è il preferito degli intagliatori, e la sua corteccia interna dava corde."),
    "sweet_chestnut": ("Europa meridionale e Asia Minore", "Un albero ampio con lunghe foglie dentate e ricci spinosi pieni di castagne. In molti paesi di montagna le castagne erano il pane dei poveri."),
    "pear": ("Europa e Asia occidentale", "Il pero: fiori bianchi in primavera e frutti succosi, coltivato dall'antichità. Il suo legno è duro e fine abbastanza da incidere matrici da stampa e righelli."),
    "elder": ("Europa, Nordafrica e Asia occidentale", "Un albero arbustivo con ombrelle piatte di fiori color crema profumati e bacche viola scuro. Le bacche vanno cotte: crude, fanno male allo stomaco."),
    "beech": ("Europa occidentale e centrale", "Un albero alto dalla corteccia liscia e grigia con un'ombra densa dove poco altro cresce. I suoi piccoli frutti, le faggiole, ingrassavano i maiali in autunno."),
    "sugar_maple": ("Canada orientale e Nordest degli Stati Uniti", "A fine inverno la sua linfa sale con circa il 3% di zucchero; quaranta litri bolliti danno un litro di sciroppo. La sua foglia è sulla bandiera del Canada."),
    "hornbeam": ("Dall'Europa all'Iran", "Un albero dal tronco grigio scanalato e dal legno più duro d'Europa. Ne venivano denti d'ingranaggio per mulini, ceppi da macellaio e martelletti di pianoforte."),
    "southern_magnolia": ("Sudest degli Stati Uniti", "Un sempreverde con foglie lucide ed enormi fiori bianchi che sanno di limone. Le magnolie sono una stirpe antica, impollinata dai coleotteri prima che esistessero le api."),
    "tulip_tree": ("Nordamerica orientale", "Una delle latifoglie più alte dell'Est, con foglie dal profilo di tulipano e fiori verdi e arancioni simili a tulipani."),
    "paulownia": ("Cina centrale e occidentale", "Uno degli alberi a crescita più rapida, con foglie enormi e fiori viola. In Giappone il suo legno leggero faceva le cassapanche donate alle figlie per le nozze."),
    "judas_tree": ("Europa meridionale e Asia occidentale", "In primavera fiori rosa porpora spuntano direttamente dal tronco e dai rami, prima delle foglie. I fiori sono commestibili e hanno un sapore agrodolce."),
    "quaking_aspen": ("Canada e Stati Uniti occidentali", "Le sue foglie tremano alla minima brezza. Un bosco dello Utah, Pando, è una sola pianta con 47.000 fusti che condividono un unico apparato radicale."),
    "alder": ("Europa, Nordafrica e Asia occidentale", "Un albero ripariale le cui radici fissano l'azoto con batteri. Il suo legno dura sott'acqua: Venezia poggia su pali di ontano."),
    "rowan": ("Europa e Asia settentrionale", "Un piccolo albero con foglie pennate e grappoli di bacche scarlatte che gli uccelli spogliano in autunno. L'acido sorbico, un comune conservante, fu scoperto in esse."),
    "black_cherry": ("Nordamerica orientale e Messico", "Un ciliegio di bosco dalla corteccia scura e squamosa. Il suo legno bruno rossastro è pregiato per i mobili; foglie e semi sono velenosi per il bestiame."),
    "yew": ("Europa, Nordafrica e Asia occidentale", "Un sempreverde scuro che può vivere oltre 2.000 anni. Quasi ogni sua parte è velenosa; il suo legno elastico fece l'arco lungo inglese, e un suo parente diede il taxolo contro il cancro."),
    "black_walnut": ("Stati Uniti orientali", "Un noce alto dal legno scuro e pregiato e dalle noci a guscio spesso. I malli verdi macchiano mani e stoffe di marrone scuro."),
    "holly": ("Europa occidentale e meridionale", "Un sempreverde con foglie lucide e spinose; solo le piante femmina portano le bacche rosse. Le foglie alte, fuori dalla portata dei cervi, spesso perdono le spine."),
    "bald_cypress": ("Sudest degli Stati Uniti", "Una conifera di palude che perde gli aghi d'inverno. Dalle sue radici spuntano 'ginocchia' nodose sopra l'acqua; il suo legno resiste alla marcescenza per secoli."),
    "water_tupelo": ("Sudest degli Stati Uniti", "Un albero di palude con la base rigonfia che sta per mesi nell'acqua. Le api ricavano dai suoi fiori un miele chiaro che non cristallizza mai."),
    "white_willow": ("Europa e Asia occidentale", "Un salice ripariale dalle foglie argentate. La sua corteccia contiene salicina, il modello naturale dell'aspirina; un suo ibrido dà il legno delle mazze da cricket."),
    "red_maple": ("Nordamerica orientale", "L'albero più comune del Nordamerica orientale, rosso nei fiori, nei piccioli e nelle foglie d'autunno. Anche la sua linfa si raccoglie, ma dà meno zucchero dell'acero da zucchero."),
    "ginkgo": ("Cina sudoccidentale", "Un fossile vivente, l'ultimo di un gruppo che cresceva con i dinosauri. Le sue foglie a ventaglio diventano dorate tutte insieme in autunno; sei ginkgo sopravvissero alla bomba di Hiroshima."),
    "japanese_maple": ("Giappone, Corea e Cina", "Un piccolo acero con foglie profondamente incise che in autunno si infiammano di rosso. I giardinieri giapponesi ne hanno selezionato centinaia di forme in tre secoli."),
    "sugi": ("Giappone", "L'albero nazionale del Giappone, una conifera altissima piantata intorno ai santuari. Si pensa che alcuni sugi dell'isola di Yakushima abbiano più di 2.000 anni."),
    "lacquer_tree": ("Cina e Himalaya", "La sua linfa, l'urushi, indurisce all'aria umida nella lacca lucida delle ciotole dell'Asia orientale. La linfa cruda brucia la pelle come l'edera velenosa, sua parente."),
    "cork_oak": ("Mediterraneo occidentale", "Una quercia sempreverde dalla corteccia spessa e spugnosa che si scorteccia ogni nove anni senza uccidere l'albero. Il Portogallo produce metà del sughero mondiale."),
    "olive": ("Bacino del Mediterraneo", "Un sempreverde nodoso dalle foglie grigio argento, coltivato per l'olio da 6.000 anni. Gli olivi possono vivere e fruttificare per più di mille anni."),
    "cedar_of_lebanon": ("Montagne di Libano, Siria e Turchia", "Una conifera maestosa con rami piatti a piani, sulla bandiera del Libano. Il suo legno profumato e duraturo costruì templi e navi del mondo antico."),
    "black_pine": ("Europa meridionale e Turchia", "Un pino dagli aghi lunghi, rigidi e scuri che sopporta siccità, vento e suoli poveri. Si incide per la resina e si pianta come frangivento."),
    "carob": ("Mediterraneo orientale", "Un sempreverde con lunghi baccelli bruni di polpa dolce. I suoi semi hanno un peso così regolare che diventarono il carato, l'unità di gemme e oro."),
    "stone_pine": ("Bacino del Mediterraneo", "Il pino domestico di Roma, dalla chioma piatta ed espansa. I suoi grandi semi sono i pinoli del pesto e dei dolci mediterranei."),
    "aleppo_pine": ("Bacino del Mediterraneo", "Un pino resistente alla siccità delle coste calde. Il vino greco retsina fu aromatizzato in origine dalla sua resina, usata per sigillare le anfore."),
    "monterey_cypress": ("Due boschetti sulla costa della California centrale", "Spontaneo solo in due boschetti costieri, ma piantato in tutto il mondo come frangivento. I venti dell'oceano lo scolpiscono in forme dalla cima piatta."),
    "apple": ("Monti Tian Shan dell'Asia centrale", "Il melo da frutteto, discendente dei meli selvatici del Kazakistan. I semi non riproducono mai la varietà: ogni varietà con un nome è innestata da un unico albero originale."),
    "balsam_fir": ("Canada e Nordest degli Stati Uniti", "Un abete profumato con vesciche di resina limpida nella corteccia. La sua resina, il balsamo del Canada, incollava vetrini e lenti da microscopio perché rifrange come il vetro."),
    "silver_fir": ("Montagne dell'Europa centrale e meridionale", "Un abete alto dalla corteccia bianco argento e aghi con due bande bianche sotto. Fu il primo albero di Natale dell'Alsazia."),
    "douglas_fir": ("Nordamerica occidentale", "Uno degli alberi più alti della Terra, con pigne le cui brattee sembrano code di topo. Il suo legno robusto costruì ponti, alberi di nave e case."),
    "siberian_fir": ("Siberia e Urali", "Un abete stretto della taiga, molto resistente al freddo. L'olio distillato dai suoi aghi si usa in medicina e nei saponi profumati."),
    "green_alder": ("Montagne e tundra dell'emisfero settentrionale", "Un ontano arbustivo dei canaloni da valanga e della tundra. Si piega sotto la neve senza rompersi e fissa l'azoto nei suoli poveri."),
    "sycamore_maple": ("Montagne dell'Europa centrale e meridionale", "Un grande acero con semi alati che girano come elicotteri. Il suo legno chiaro fa i fondi dei violini e i tavoli da cucina."),
    "atlas_cedar": ("Monti dell'Atlante in Marocco e Algeria", "Un cedro di montagna con aghi verde azzurro a ciuffi. Nelle sue foreste vivono i macachi berberi, e quelle foreste si riducono per la siccità e il pascolo eccessivo."),
    "siberian_pine": ("Siberia e Mongolia", "Il 'cedro' siberiano, un pino a cinque aghi con grandi pinoli senza ala. Le nocciolaie spargono i semi sotterrandoli per l'inverno."),
    "western_red_cedar": ("Nordovest pacifico del Nordamerica", "Una conifera enorme delle coste piovose con corteccia fibrosa. Il suo legno imputrescibile diede ai popoli della costa canoe, case e totem."),
    "sea_buckthorn": ("Europa e Asia", "Un arbusto spinoso di dune e ghiaie con foglie argentate. Le sue bacche arancioni restano attaccate ai rami e sono ricche di vitamina C e olio."),
    "european_larch": ("Alpi e Carpazi", "Una conifera che si fa dorata e perde gli aghi ogni autunno. La sua resina, la trementina veneta, era usata dai pittori, e il suo legno resiste alla marcescenza."),
    "dahurian_larch": ("Siberia orientale e Asia nordorientale", "L'albero più settentrionale della Terra, che cresce sul permafrost a 72° nord. Sopravvive a inverni sotto i 60 °C sotto zero."),
    "siberian_dwarf_pine": ("Siberia nordorientale e Giappone", "Un pino strisciante che d'inverno si sdraia sotto la neve e in primavera si rialza. I suoi pinoli nutrono orsi e zibellini."),
    "eastern_white_pine": ("Canada orientale e Nordest degli Stati Uniti", "L'albero più alto del Nordamerica orientale, con aghi morbidi a gruppi di cinque. La Corona britannica riservava i più grandi agli alberi maestri della sua flotta."),
    "bristlecone_pine": ("White Mountains e Grande Bacino, Stati Uniti", "Gli alberi viventi più vecchi: uno, Matusalemme, ha più di 4.800 anni. I loro anelli sono serviti a calibrare la datazione al radiocarbonio."),
    "swiss_pine": ("Alpi e Carpazi", "Un pino lento a cinque aghi vicino al limite degli alberi, dal legno profumato usato per le stube alpine. I suoi semi li sparge la nocciolaia."),
    "whitebark_pine": ("Montagne del Nordamerica occidentale", "Un pino d'alta montagna le cui pigne non si aprono mai da sole; le rompe la nocciolaia di Clark. La ruggine vescicolosa e i coleotteri lo stanno uccidendo."),
    "lodgepole_pine": ("Nordamerica occidentale", "Diritto e sottile, i popoli delle pianure lo usavano per i pali dei tepee. Molte sue pigne si aprono solo al calore di un incendio boschivo."),
    "mountain_pine": ("Montagne dell'Europa centrale e meridionale", "Un pino basso a molti fusti del limite alpino degli alberi che trattiene neve e suolo sui pendii ripidi. Il suo olio si usa nei rimedi per la tosse."),
    "scots_pine": ("Europa e Asia settentrionale", "Il pino più diffuso al mondo, con la corteccia arancione in alto. La sua resina diede trementina e pece per le funi e gli scafi dei velieri."),
    "arctic_willow": ("Tundra artica", "Un albero alto una spanna che striscia sulla tundra. I suoi fusti possono avere secoli; le sue foglie nutrono buoi muschiati e lepri."),
    "coast_redwood": ("Costa della California settentrionale e dell'Oregon meridionale", "Gli alberi più alti della Terra: Hyperion misura 116 metri. La nebbia del Pacifico dà loro acqua nell'estate secca."),
    "giant_sequoia": ("Versanti occidentali della Sierra Nevada", "Gli alberi più grandi per volume: il General Sherman pesa circa 2.000 tonnellate. La sua corteccia è spessa mezzo metro e resiste al fuoco."),
    "western_hemlock": ("Nordovest pacifico del Nordamerica", "Una conifera d'ombra con la cima ricadente che cresce sotto altri alberi. La sua corteccia è ricca di tannino e la sua polpa fa carta."),
    "common_juniper": ("Tutto l'emisfero settentrionale", "La conifera più diffusa della Terra, un arbusto di brughiere e tundra. I suoi coni blu, le bacche di ginepro, aromatizzano il gin."),
    "araucaria": ("Brasile meridionale e Argentina nordorientale", "Una conifera a candelabro i cui rami finiscono in ciuffi in cima. I suoi grandi semi, il pinhão, sono un cibo autunnale nel sud del Brasile; il taglio ha lasciato solo pochi punti percentuali delle sue foreste."),
    "brazilian_rosewood": ("Foresta atlantica del Brasile", "Palissandro di Rio: durame scuro, profumato e venato, un tempo il migliore per chitarre e mobili. Dal 1992 il suo commercio internazionale è vietato."),
    "mango": ("India, Bangladesh e Myanmar", "Un grande sempreverde coltivato da 4.000 anni per il frutto dolce. La sua linfa e la buccia contengono lo stesso irritante dell'edera velenosa, una parente."),
    "avocado": ("Messico e America centrale", "Un alloro sempreverde il cui frutto è ricco di olio, non di zucchero. Il suo grande seme forse era disperso da bradipi giganti oggi estinti."),
    "cashew": ("Nordest del Brasile", "La noce pende sotto una 'mela' carnosa che si mangia come frutto o succo. Il guscio contiene un olio caustico, perciò le noci si tostano prima di aprirle."),
    "orange": ("Cina meridionale e Sudest asiatico (coltivato)", "L'arancio dolce, un antico incrocio di pomelo e mandarino. Il Brasile produce più arance di qualsiasi altro paese."),
    "lemon": ("India nordorientale e Myanmar (coltivato)", "Un sempreverde spinoso il cui frutto aspro è ricco di vitamina C e acido citrico. Una razione di succo di limone proteggeva i marinai dallo scorbuto."),
    "papaya": ("Messico meridionale e America centrale", "Un albero rapido dal fusto tenero che fruttifica il primo anno. Il suo lattice contiene papaina, un enzima che scompone la carne."),
    "kapok": ("Americhe tropicali e Africa occidentale", "Un gigante con radici a contrafforte che sovrasta la volta della foresta pluviale. I suoi baccelli danno una fibra leggera e impermeabile che un tempo riempiva i giubbotti di salvataggio; i Maya lo ritenevano sacro."),
    "sweet_cherry": ("Europa e Asia occidentale", "Il ciliegio selvatico, progenitore delle ciliegie dolci da frutteto. Il suo legno rossastro è pregiato dagli ebanisti, e gli uccelli ne spargono i noccioli."),
    "plum": ("Europa e Asia occidentale (coltivato)", "Il susino europeo, un antico ibrido da frutteto. Le susine secche sono le prugne secche; il suo frutto blu ha una pruina di cera."),
    "peach": ("Cina nordoccidentale (coltivato)", "Un piccolo albero con fiori rosa in primavera e frutti vellutati. In Cina la pesca simboleggia la lunga vita."),
    "apricot": ("Asia centrale e Cina", "Un albero da frutto a fioritura precoce delle montagne secche. I suoi semi danno un olio e, crudi, un veleno amaro come quello delle mandorle amare."),
    "fig": ("Asia sudoccidentale e Mediterraneo", "Il suo 'frutto' è un'infiorescenza rovesciata, impollinata da una minuscola vespa che ci entra dentro. I fichi furono tra le prime piante coltivate dall'uomo."),
    "pomegranate": ("Dall'Iran all'India settentrionale", "Un albero arbustivo il cui frutto coriaceo racchiude centinaia di semi rossi e succosi. La sua scorza è ricca di tannino e tingeva i tappeti orientali."),
    "almond": ("Asia sudoccidentale", "Un parente del pesco coltivato per il seme. Le mandorle selvatiche sono amare e velenose; la perdita di un solo gene ha dato la mandorla dolce che mangiamo."),
    "pistachio": ("Asia centrale e Iran", "Un albero del deserto le cui noci mature aprono il guscio. Ci sono piante maschio e femmina, perciò nei frutteti si pianta un maschio ogni otto femmine."),
    "hazel": ("Europa e Asia occidentale", "Un alberello a molti fusti con amenti a fine inverno. Con i suoi polloni diritti si intrecciavano recinti, e da esso si tagliavano le bacchette da rabdomante."),
    "pecan": ("Valle del Mississippi e Messico", "Un alto hickory dei fondovalle con noci dolci dal guscio sottile. Fu cibo dei nativi americani molto prima di diventare una coltura."),
    "plane_tree": ("Dall'Europa sudorientale all'Iran", "Un ampio albero da ombra la cui corteccia si stacca a placche. Si dice che Ippocrate insegnasse sotto uno di essi sull'isola di Kos."),
    "horse_chestnut": ("Montagne dei Balcani", "Un albero ampio con candele di fiori bianchi e castagne d'India brune e lucide. I suoi semi sono velenosi per le persone nonostante il nome."),
}

